"""Build a VPM zip while retaining Unity GUID metadata and excluding local outputs."""

import argparse
import json
from pathlib import Path
import stat
from zipfile import ZIP_DEFLATED, ZipFile, ZipInfo


ASS_PROBES = {
    "Editor/AnimationPathBindingProbe.cs",
    "Editor/AssetBundlePathBindingProbeBuilder.cs",
    "Runtime/AnimationPathBindingProbe.cs",
    "Runtime/BundleProbeSceneRunner.cs",
}


def include_file(relative_path, package_name):
    # Treat metadata exactly like the asset it belongs to.
    asset = relative_path.removesuffix(".meta")
    parts = Path(asset).parts
    if any(part in {"Generated", ".git", "__pycache__"} for part in parts):
        return False
    if package_name == "top.sealoong.unitybox.avatar-security-system":
        if asset in ASS_PROBES:
            return False
        # Keep Editor regression tests; these older fixtures are generated by
        # the experiment menus and have machine-specific GUIDs/build targets.
        if asset == "Tests/Bundles" or asset.startswith("Tests/Bundles/"):
            return False
        if asset.startswith("Tests/") and len(parts) == 2 and Path(asset).suffix in {
            ".anim", ".controller", ".prefab", ".unity"
        }:
            return False
    return True


def build_package(source, destination):
    source, destination = Path(source), Path(destination)
    package_name = json.loads((source / "package.json").read_text(encoding="utf-8"))["name"]
    missing = [path.relative_to(source).as_posix() for path in source.rglob("*")
               if path.is_file() and path.suffix in {".cs", ".asmdef"}
               and include_file(path.relative_to(source).as_posix(), package_name)
               and not path.with_name(path.name + ".meta").is_file()]
    if missing:
        raise ValueError("Unity scripts and assemblies require stable .meta files before publishing: " + ", ".join(sorted(missing)))
    destination.parent.mkdir(parents=True, exist_ok=True)
    with ZipFile(destination, "w", ZIP_DEFLATED, compresslevel=9) as archive:
        for path in sorted(source.rglob("*")):
            if path.is_file() and include_file(path.relative_to(source).as_posix(), package_name):
                entry = ZipInfo(path.relative_to(source).as_posix(), date_time=(1980, 1, 1, 0, 0, 0))
                entry.create_system = 3
                permissions = 0o755 if path.stat().st_mode & 0o111 else 0o644
                entry.external_attr = (stat.S_IFREG | permissions) << 16
                archive.writestr(entry, path.read_bytes(), compress_type=ZIP_DEFLATED, compresslevel=9)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    build_package(args.source, args.destination)
